use neo4j::Session;
use neo4j::types::Value;
use neo4j::query::Query;

pub struct GraphDatabase {
    session: Session,
}

impl GraphDatabase {
    pub fn new(uri: &str, user: &str, password: &str) -> Self {
        let session = Session::new(uri, user, password).expect("Failed to create Neo4j session");
        GraphDatabase { session }
    }

    pub fn store_data(&self, sensor_id: &str, value: &str, posterior: f64) {
        let query = Query::new("CREATE (s:Sensor {id: $id, value: $value, posterior: $posterior})");
        let params = HashMap::from([
            ("id", Value::String(sensor_id.to_string())),
            ("value", Value::String(value.to_string())),
            ("posterior", Value::Float(posterior)),
        ]);

        self.session.run(&query, &params).expect("Failed to store data in Neo4j");
    }
}

